    const r=await fetch(u,{headers:{'user-agent':'maps-n-stuff/0.2'}});
    if(!r.ok) return {id:doc.id,status:r.status};
    const m=await r.json();
    const labels=[...new Set((m.metadata||[]).map(x=>Object.values(x.label||{})[0]?.[0]).filter(Boolean))];
    return {id:doc.id,status:r.status,rights:m.rights, canvases:m.items?.length, labels, nav:!!m.navPlace, thumb:!!m.thumbnail, prov:m.provider?.[0]?.label?.en?.[0]};
  }catch(e){return {id:doc.id,status:'err',e:String(e)}}
}
for(let i=0;i<ids.length;i+=6){ out.push(...await Promise.all(ids.slice(i,i+6).map((id)=>one(d.data.find(x=>x.id===id))))); }
for(const o of out) console.log(JSON.stringify(o));
const labels=new Set(); out.forEach(o=>o.labels?.forEach(l=>labels.add(l)));
console.log('ALL LABELS', [...labels].sort().join(' | '));
EOF
