#!/usr/bin/env node
/**
 * Reproducible harvest of Princeton University Library's Figgy scanned maps.
 *
 * Discovery uses the documented Blacklight JSON catalogue
 * (https://figgy.princeton.edu/catalog.json) with the `Scanned Map` type and
 * the catalogue's own `No Known Copyright` rights facet. The sparse catalogue
 * JSON does not carry a rights statement, so every rights decision is made
 * from that item's IIIF Presentation 3 manifest
 * (https://figgy.princeton.edu/concern/scanned_maps/<uuid>/manifest), which
 * states the rightsstatements.org URI, the owning provider, a navPlace
 * footprint, the label and the image service.
 *
 * Only affirmative public-domain / attribution-only rights URIs are admitted:
 *   NKC/1.0, NoC-US/1.0, PDM/1.0, CC0 1.0, CC BY (not NC/ND).
 * Copyright Not Evaluated, In Copyright, NoC-OKLR and every unstated or
 * non-commercial/No-Derivatives licence stay out. The URI is retained verbatim
 * on every record.
 *
 * Usage:
 *   node scripts/harvest-princeton.mjs                  # cached, full eligible set
 *   node scripts/harvest-princeton.mjs --limit 40       # smoke test, no write
 *   node scripts/harvest-princeton.mjs --refresh        # re-fetch discovery + manifests
 *   node scripts/harvest-princeton.mjs --no-write       # report only
 *   node scripts/harvest-princeton.mjs --max-pages 3    # discovery smoke test
 *
 * The result is written to its own static shard (`/data/records/princeton.json`)
 * so the core catalogue stays under Cloudflare's per-asset limit. Re-running
 * replaces only `princeton:` records and preserves every other provider.
 */
import { mkdir, readFile, writeFile, rename } from 'node:fs/promises';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { shardPath, shardUrl } from './catalogue.mjs';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const args = process.argv.slice(2);
const has = (flag) => args.includes(`--${flag}`);
const value = (name, fallback) => {
  const index = args.indexOf(`--${name}`);
  return index >= 0 && args[index + 1] ? args[index + 1] : fallback;
};
const OUT = resolve(value('out', resolve(ROOT, 'public/data')));
const CACHE = resolve(ROOT, '.cache/princeton');
const REFRESH = has('refresh');
const WRITE = !has('no-write') && !has('limit');
const LIMIT = Math.max(0, Number(value('limit', '0')) || 0);
const MAX_PAGES = Math.max(0, Number(value('max-pages', '0')) || 0);
const CONCURRENCY = Math.max(1, Math.min(6, Number(value('concurrency', '4')) || 4));
const PAGE_SIZE = 100;
const RETRIEVED = '2026-10-20';
const UA = 'maps-n-stuff/0.2 (+https://github.com/igor-makarov/maps-n-stuff; historical map catalogue)';
const DISCOVERY = 'https://figgy.princeton.edu/catalog.json';
const DISCOVERY_QUERY =
  'f%5Bhuman_readable_type_ssim%5D%5B%5D=Scanned+Map&f%5Brights_ssim%5D%5B%5D=No+Known+Copyright';
const MANIFEST = (uuid) => `https://figgy.princeton.edu/concern/scanned_maps/${uuid}/manifest`;
const RECORD_URL = (uuid) => `https://figgy.princeton.edu/catalog/${uuid}`;

const sleep = (ms) => new Promise((done) => setTimeout(done, ms));

async function fetchJson(url, { attempts = 4 } = {}) {
  let last;
  for (let attempt = 1; attempt <= attempts; attempt++) {
    try {
      const response = await fetch(url, { headers: { accept: 'application/json', 'user-agent': UA } });
      if (response.ok) return await response.json();
      last = new Error(`${response.status} ${url}`);
      if (response.status !== 429 && response.status < 500) break;
    } catch (error) {
      last = error;
    }
    await sleep(500 * attempt);
  }
  throw last;
}

async function cachedJson(url, path) {
  if (!REFRESH) {
    try {
      return JSON.parse(await readFile(path, 'utf8'));
    } catch {}
  }
  const body = await fetchJson(url);
  await mkdir(dirname(path), { recursive: true });
  const temp = `${path}.tmp-${process.pid}`;
  await writeFile(temp, JSON.stringify(body));
  await rename(temp, path);
  return body;
}

async function pool(items, limit, fn) {
  const output = new Array(items.length);
  let next = 0;
  async function worker() {
    while (true) {
      const index = next++;
      if (index >= items.length) return;
      output[index] = await fn(items[index], index);
      await sleep(80);
    }
  }
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker));
  return output;
}

/** First value of a Presentation 3 language map / value object, English first. */
export function firstLabel(value) {
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) {
    for (const item of value) {
      const text = firstLabel(item);
      if (text) return text;
    }
    return '';
  }
  if (!value || typeof value !== 'object') return '';
  if (value.en) {
    const text = firstLabel(value.en);
    if (text) return text;
  }
  for (const entry of Object.values(value)) {
    const text = firstLabel(entry);
    if (text) return text;
  }
  return '';
}

/** All values of one metadata label, keeping the manifest's language variants. */
export function metadataValues(manifest, labels) {
  const wanted = new Set(labels);
  const values = [];
  for (const entry of Array.isArray(manifest?.metadata) ? manifest.metadata : []) {
    const label = firstLabel(entry?.label);
    if (!wanted.has(label)) continue;
    const raw = entry?.value;
    const list = Array.isArray(raw) ? raw : [raw];
    for (const item of list) {
      const text = firstLabel(item).replace(/\s+/g, ' ').trim();
      if (text && !values.includes(text)) values.push(text);
    }
  }
  return values;
}

/**
 * Rights gate. Returns a named basis or null; it never guesses. The upstream
 * URI stays on the record, so a reviewer can re-check the determination.
 */
export function rightsBasis(uri) {
  const raw = String(uri ?? '').trim();
  if (!raw) return null;
  const value = raw.toLowerCase().replace(/\/+$/, '');
  if (/rightsstatements\.org\/vocab\/nkc\/1\.0$/.test(value)) return 'nkc';
  if (/rightsstatements\.org\/vocab\/noc-us\/1\.0$/.test(value)) return 'no-copyright-us';
  if (/rightsstatements\.org\/vocab\/pdm\/1\.0$/.test(value)) return 'public-domain-mark';
  if (/creativecommons\.org\/publicdomain\/zero\/1\.0$/.test(value)) return 'cc0';
  if (/creativecommons\.org\/licenses\/by\/(?!.*(?:nc|nd))/.test(value)) return 'cc-by';
  return null;
}

const RIGHTS_LABEL = {
  nkc: 'No Known Copyright',
  'no-copyright-us': 'No Copyright - United States',
  'public-domain-mark': 'Public Domain Mark',
  cc0: 'CC0 1.0',
  'cc-by': 'Creative Commons Attribution',
};

/** Conservative publication years: Date metadata first, then an unambiguous imprint year. */
export function publicationYears(manifest) {
  const yearsIn = (texts) => {
    const found = [];
    for (const text of texts) {
      for (const match of String(text).matchAll(/\b(1[4-9][0-9]{2}|20[0-9]{2}|2100)\b/g)) {
        const year = Number(match[1]);
        if (year >= 1400 && year <= 2100) found.push(year);
      }
    }
    return found;
  };
  const dated = yearsIn(metadataValues(manifest, ['Date']));
  if (dated.length) return { start: Math.min(...dated), end: Math.max(...dated), source: 'Date' };
  const publisherYears = yearsIn(metadataValues(manifest, ['Publisher']));
  const unique = [...new Set(publisherYears)];
  if (unique.length === 1) return { start: unique[0], end: unique[0], source: 'Publisher imprint' };
  return { start: null, end: null, source: null };
}

/** Bounding box of every navPlace polygon; null when the manifest states none. */
export function navPlaceExtent(manifest) {
  const features = manifest?.navPlace?.features;
  if (!Array.isArray(features) || features.length === 0) return null;
  const lons = [];
  const lats = [];
  const flatten = (coordinates) => {
    if (!Array.isArray(coordinates)) return;
    if (coordinates.length >= 2 && Number.isFinite(coordinates[0]) && Number.isFinite(coordinates[1])) {
      lons.push(coordinates[0]);
      lats.push(coordinates[1]);
      return;
    }
    for (const child of coordinates) flatten(child);
  };
  for (const feature of features) flatten(feature?.geometry?.coordinates);
  if (!lons.length || !lats.length) return null;
  const extent = {
    west: Math.min(...lons),
    east: Math.max(...lons),
    south: Math.min(...lats),
    north: Math.max(...lats),
  };
  if (![extent.west, extent.east, extent.south, extent.north].every(Number.isFinite)) return null;
  if (extent.west < -180 || extent.east > 180 || extent.south < -90 || extent.north > 90) return null;
  if (extent.west >= extent.east || extent.south >= extent.north) return null;
  return extent;
}

function imageServiceOf(manifest) {
  const canvas = Array.isArray(manifest?.items) ? manifest.items[0] : null;
  const annotation = canvas?.items?.[0]?.items?.[0];
  const service = annotation?.body?.service;
  const candidate = Array.isArray(service) ? service[0] : service;
  const id = candidate?.['@id'] ?? candidate?.id ?? '';
  return /^https:\/\/iiif-cloud\.princeton\.edu\/iiif\/2\//.test(String(id)) ? String(id) : '';
}

function thumbnailOf(manifest, imageService) {
  const thumbnail = Array.isArray(manifest?.thumbnail) ? manifest.thumbnail[0] : manifest?.thumbnail;
  const id = typeof thumbnail === 'string' ? thumbnail : thumbnail?.id ?? '';
  if (/^https:\/\/iiif-cloud\.princeton\.edu\//.test(String(id))) return String(id);
  if (imageService) return `${imageService}/full/304,/0/default.jpg`;
  return '';
}

/** Build one record from a manifest, or explain why it is withheld. */
export function princetonRecord(manifest, document) {
  const uuid = String(document?.id ?? '');
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(uuid)) {
    return { record: null, reason: 'invalid Figgy UUID' };
  }
  const basis = rightsBasis(manifest?.rights);
  if (!basis) {
    return { record: null, reason: `rights withheld: ${String(manifest?.rights ?? 'unstated')}` };
  }
  const title = firstLabel(manifest?.label) || metadataValues(manifest, ['Title'])[0] || '';
  if (!title) return { record: null, reason: 'manifest has no title' };
  const imageService = imageServiceOf(manifest);
  const thumbnail = thumbnailOf(manifest, imageService);
  if (!imageService || !thumbnail) return { record: null, reason: 'manifest has no Princeton image service' };
  const canvases = Array.isArray(manifest?.items) ? manifest.items.length : 0;
  if (canvases === 0) return { record: null, reason: 'manifest has no canvases' };

  const extent = navPlaceExtent(manifest);
  const years = publicationYears(manifest);
  const creatorFields = ['Creator', 'Author', 'Cartographer', 'Contributor', 'Engraver', 'Printer', 'Issuing Body'];
  const creators = metadataValues(manifest, creatorFields);
  const publisher = metadataValues(manifest, ['Publisher']);
  const languages = metadataValues(manifest, ['Language']);
  const spatial = metadataValues(manifest, ['Spatial']);
  const subjects = metadataValues(manifest, ['Subject']);
  const collection = metadataValues(manifest, ['Member Of Collections']);
  const callNumber = metadataValues(manifest, ['Call Number'])[0] ?? String(document?.attributes?.call_number_tsim?.attributes?.value ?? '');
  const titleAlt = metadataValues(manifest, ['Title', 'Alternative']).filter((text) => text !== title);
  const dateDisplay = metadataValues(manifest, ['Date']).join('; ');
  const heldBy = metadataValues(manifest, ['Held By'])[0] || firstLabel(manifest?.provider?.[0]?.label) || 'Princeton University Library';

  const record = {
    id: `princeton:${uuid}`,
    title,
    titleAlt,
    creators,
    providerId: 'princeton',
    institution: heldBy,
    rights: `${RIGHTS_LABEL[basis]} — ${String(manifest.rights)}`,
    rightsBasis: basis,
    rightsUri: String(manifest.rights),
    recordUrl: RECORD_URL(uuid),
    iiifManifest: MANIFEST(uuid),
    thumbnail,
    imageService,
    type: 'map',
    collection: collection.join('; '),
    publisher: publisher[0] ?? '',
    imprint: publisher.join('; '),
    dateDisplay,
    languages,
    subjectPlace: spatial.join('; '),
    subjects,
    shelfmark: callNumber,
    scale: metadataValues(manifest, ['Cartographic Scale'])[0] ?? '',
    edition: metadataValues(manifest, ['Edition'])[0] ?? '',
    sheetCount: canvases,
    extent,
    geoNote: extent
      ? 'Footprint from the Princeton IIIF navPlace feature; it is a catalogued map extent, not a verified image georeference.'
      : 'The Princeton IIIF manifest states no navPlace footprint for this scan; no boundary or image alignment is inferred.',
  };
  if (years.start != null) {
    record.yearStart = years.start;
    record.yearEnd = years.end;
    record.yearSource = years.source;
  }
  if (extent) record.geo = { lat: (extent.south + extent.north) / 2, lon: (extent.west + extent.east) / 2 };
  // The schema treats an absent field as unknown; do not ship long runs of nulls.
  for (const key of Object.keys(record)) {
    const current = record[key];
    if (Array.isArray(current) && current.length === 0) delete record[key];
    else if (current == null || current === '') delete record[key];
  }
  return { record, reason: null };
}

async function discoveryPage(page) {
  const path = resolve(CACHE, 'pages', `page-${page}.json`);
  const url = `${DISCOVERY}?${DISCOVERY_QUERY}&per_page=${PAGE_SIZE}&page=${page}`;
  return cachedJson(url, path);
}

async function manifestFor(uuid) {
  const path = resolve(CACHE, 'manifests', `${uuid}.json`);
  return cachedJson(MANIFEST(uuid), path);
}

async function verify(records) {
  const sample = [];
  const step = Math.max(1, Math.floor(records.length / 30));
  for (let index = 0; index < records.length && sample.length < 30; index += step) sample.push(records[index]);
  const results = await pool(sample, 3, async (record) => {
    const image = await fetch(record.thumbnail, {
      headers: { accept: 'image/jpeg', 'user-agent': UA, range: 'bytes=0-2047' },
    }).catch(() => null);
    const info = await fetch(`${record.imageService}/info.json`, {
      headers: { accept: 'application/json', 'user-agent': UA },
    }).catch(() => null);
    return {
      id: record.id,
      thumbnail: image?.status ?? 0,
      thumbnailType: image?.headers.get('content-type') ?? '',
      info: info?.status ?? 0,
      infoType: info?.headers.get('content-type') ?? '',
    };
  });
  return {
    retrieved: RETRIEVED,
    sample: results.length,
    thumbnailOk: results.filter((result) => result.thumbnail === 200 && /image\//.test(result.thumbnailType)).length,
    imageInfoOk: results.filter((result) => result.info === 200 && /json/.test(result.infoType)).length,
    examples: results.slice(0, 5),
  };
}

async function main() {
  const first = await discoveryPage(1);
  const total = first.meta?.pages?.total_count ?? 0;
  const pages = Math.min(MAX_PAGES || Infinity, first.meta?.pages?.total_pages ?? 1);
  console.log(`Princeton Figgy discovery: ${total} Scanned Map records with the No Known Copyright facet in ${first.meta?.pages?.total_pages} pages; reading ${pages}`);
  const documents = [...(first.data ?? [])];
  let next = 2;
  async function discoveryWorker() {
    while (true) {
      const page = next++;
      if (page > pages) return;
      const body = await discoveryPage(page);
      documents.push(...(body.data ?? []));
      if (page % 15 === 0) console.log(`discovery page ${page}/${pages}`);
      await sleep(100);
    }
  }
  await Promise.all(Array.from({ length: 3 }, discoveryWorker));

  const seen = new Set();
  const unique = [];
  for (const document of documents) {
    if (!document?.id || seen.has(document.id)) continue;
    seen.add(document.id);
    unique.push(document);
  }
  const candidates = LIMIT ? unique.slice(0, LIMIT) : unique;
  console.log(`Unique records: ${unique.length}; fetching ${candidates.length} manifests`);

  let done = 0;
  const failures = {};
  const built = await pool(candidates, CONCURRENCY, async (document) => {
    try {
      const manifest = await manifestFor(document.id);
      done += 1;
      if (done % 500 === 0) console.log(`manifests ${done}/${candidates.length}`);
      return princetonRecord(manifest, document);
    } catch (error) {
      done += 1;
      const reason = `manifest error: ${String(error?.message ?? error).slice(0, 120)}`;
      failures[reason] = (failures[reason] || 0) + 1;
      return { record: null, reason };
    }
  });

  const records = [];
  const rejected = {};
  for (const { record, reason } of built) {
    if (!record) {
      rejected[reason] = (rejected[reason] || 0) + 1;
      continue;
    }
    if (records.some((existing) => existing.id === record.id)) continue;
    records.push(record);
  }
  if (!records.length) throw new Error('No eligible Princeton records; leaving the catalogue unchanged.');
  records.sort((a, b) => (a.yearStart ?? Infinity) - (b.yearStart ?? Infinity) || a.id.localeCompare(b.id));

  const basis = {};
  for (const record of records) basis[record.rightsBasis] = (basis[record.rightsBasis] || 0) + 1;
  console.log(`Eligible Princeton records: ${records.length}`);
  console.log('Rights bases:', basis);
  console.log('With extents:', records.filter((record) => record.extent).length, 'undated:', records.filter((record) => record.yearStart == null).length);
  console.log('Withheld:', rejected);
  const verification = await verify(records);
  console.log('Verification sample:', verification);

  const shard = shardUrl('princeton');
  const selection = {
    discovered: total,
    pagesRead: pages,
    uniqueRecords: unique.length,
    considered: candidates.length,
    kept: records.length,
    shard,
    rightsBasis: basis,
    withheld: rejected,
    rule:
      'Every Princeton University Library Figgy `Scanned Map` in the catalogue rights facet `No Known Copyright`, re-checked against the item IIIF manifest and admitted only for NKC/1.0, NoC-US/1.0, PDM/1.0, CC0 1.0 or CC BY (no NC/ND). Copyright Not Evaluated, In Copyright, NoC-OKLR and unstated rights stay out. Metadata only: no embargoed or empty items, no synthetic placeholders.',
    verification,
  };
  const provider = {
    id: 'princeton',
    name: 'Princeton University Library — Figgy scanned maps',
    operator: 'Princeton University Library',
    homepage: 'https://figgy.princeton.edu/',
    home: 'https://figgy.princeton.edu/',
    institutions: ['Princeton University Library'],
    rights:
      'The rightsstatements.org URI from each item IIIF manifest is retained verbatim. Imported records carry NKC/1.0, NoC-US/1.0, PDM/1.0, CC0 1.0 or CC BY (not NC/ND); Copyright Not Evaluated, In Copyright and NoC-OKLR items are withheld.',
    attribution: 'Princeton University Library',
    retrieved: RETRIEVED,
    api: {
      catalogue: `${DISCOVERY}?${DISCOVERY_QUERY}`,
      manifest: 'https://figgy.princeton.edu/concern/scanned_maps/{uuid}/manifest',
      image: 'https://iiif-cloud.princeton.edu/iiif/2/{identifier}',
      documentation: 'https://figgy.princeton.edu/',
    },
    apiHosts: ['figgy.princeton.edu', 'iiif-cloud.princeton.edu'],
    method:
      'Documented Blacklight JSON catalogue filtered to human_readable_type=Scanned Map and rights=No Known Copyright, paginated at 100 records per page; every record is rebuilt from its IIIF Presentation 3 manifest with a per-item rights gate. No decade, geography, collection or record-count cap.',
    collections: [{ id: 'figgy-scanned-maps', name: 'Figgy scanned maps', discovery: `${DISCOVERY}?${DISCOVERY_QUERY}` }],
    verification,
  };

  const recordsPath = resolve(OUT, 'records.json');
  const sourcesPath = resolve(OUT, 'sources.json');
  const recordsDoc = JSON.parse(await readFile(recordsPath, 'utf8'));
  const sourcesDoc = JSON.parse(await readFile(sourcesPath, 'utf8'));
  recordsDoc.shards = [...new Set([...(recordsDoc.shards ?? []), shard])].sort();
  recordsDoc.records = (recordsDoc.records ?? []).filter((record) => record.providerId !== 'princeton');
  recordsDoc.generatedAt = new Date().toISOString();
  recordsDoc.retrieved = RETRIEVED;
  recordsDoc.method = `${recordsDoc.method ? `${recordsDoc.method} ` : ''}Princeton University Library Figgy scanned maps are imported through the documented catalogue JSON, rebuilt from item IIIF manifests and bundled in ${shard}.`;
  recordsDoc.selection ??= {};
  recordsDoc.selection['princeton:figgy'] = selection;
  sourcesDoc.providers = [...sourcesDoc.providers.filter((source) => source.id !== 'princeton'), provider];
  sourcesDoc.generatedAt = recordsDoc.generatedAt;

  const shardDoc = {
    generatedAt: recordsDoc.generatedAt,
    retrieved: RETRIEVED,
    providerId: 'princeton',
    method: selection.rule,
    selection,
    records,
  };
  const coreBytes = Buffer.byteLength(JSON.stringify(recordsDoc));
  const shardBytes = Buffer.byteLength(JSON.stringify(shardDoc));
  console.log(
    `Catalogue would be ${recordsDoc.records.length} core + ${records.length} princeton records; ` +
      `core ${(coreBytes / 1024 / 1024).toFixed(2)} MiB, shard ${(shardBytes / 1024 / 1024).toFixed(2)} MiB`,
  );
  if (coreBytes > 24 * 1024 * 1024 || shardBytes > 24 * 1024 * 1024) {
    throw new Error('A catalogue asset exceeds 24 MiB; split it before writing.');
  }
  if (WRITE) {
    await mkdir(dirname(shardPath(OUT, shard)), { recursive: true });
    await writeFile(shardPath(OUT, shard), `${JSON.stringify(shardDoc)}\n`);
    await writeFile(recordsPath, `${JSON.stringify(recordsDoc)}\n`);
    await writeFile(sourcesPath, `${JSON.stringify(sourcesDoc, null, 2)}\n`);
    console.log('Wrote', OUT, 'and', shard);
  } else {
    console.log('Dry run: catalogue unchanged (use without --limit/--no-write to write).');
  }
}

if (process.argv[1] && import.meta.url === new URL(`file://${resolve(process.argv[1])}`).href) {
  main().catch((error) => {
    console.error(error);
    process.exit(1);
  });
}

