/**
 * Princeton University Library Figgy harvest: rights gate, manifest parsing and
 * the committed shard invariants.
 *
 * These are offline tests. The live endpoint sample is recorded in
 * `public/data/sources.json` and can be re-run with
 * `node scripts/harvest-princeton.mjs --limit 30` (no write).
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';

import {
  navPlaceExtent,
  princetonRecord,
  publicationYears,
  rightsBasis,
} from '../scripts/harvest-princeton.mjs';

const shard = JSON.parse(
  await readFile(new URL('../public/data/records/princeton.json', import.meta.url), 'utf8'),
);
const core = JSON.parse(
  await readFile(new URL('../public/data/records.json', import.meta.url), 'utf8'),
);

function fixtureManifest(overrides = {}) {
  return {
    type: 'Manifest',
    label: { eng: ['A chart of the coast'] },
    rights: 'http://rightsstatements.org/vocab/NKC/1.0/',
    provider: [{ id: 'https://library.princeton.edu', type: 'Agent', label: { en: ['Princeton University Library'] } }],
    metadata: [
      { label: { eng: ['Creator'] }, value: { eng: ['Example, Cartographer'] } },
      { label: { eng: ['Date'] }, value: { eng: ['1884'] } },
      { label: { eng: ['Publisher'] }, value: { eng: ['London : Example Press, 1884.'] } },
      { label: { eng: ['Language'] }, value: { eng: ['English'] } },
      { label: { eng: ['Spatial'] }, value: { eng: ['New Jersey'] } },
      { label: { eng: ['Call Number'] }, value: { eng: ['HMC01.1'] } },
      { label: { eng: ['Held By'] }, value: { eng: ['Princeton'] } },
      { label: { eng: ['Title'] }, value: { eng: ['A chart of the coast [map].'] } },
    ],
    items: [
      {
        type: 'Canvas',
        items: [
          {
            type: 'AnnotationPage',
            items: [
              {
                type: 'Annotation',
                body: {
                  id: 'https://iiif-cloud.princeton.edu/iiif/2/aa%2Fbb%2Fintermediate_file/full/1000,/0/default.jpg',
                  type: 'Image',
                  service: [{ '@id': 'https://iiif-cloud.princeton.edu/iiif/2/aa%2Fbb%2Fintermediate_file', profile: 'http://iiif.io/api/image/2/level2.json' }],
                },
              },
            ],
          },
        ],
      },
    ],
    thumbnail: [{ id: 'https://iiif-cloud.princeton.edu/iiif/2/cc%2Fdd%2Fthumbnail/full/!200,150/0/default.jpg' }],
    navPlace: {
      type: 'FeatureCollection',
      features: [
        {
          type: 'Feature',
          geometry: {
            type: 'Polygon',
            coordinates: [
              [
                [-75.2, 38.9],
                [-73.9, 38.9],
                [-73.9, 41.4],
                [-75.2, 41.4],
                [-75.2, 38.9],
              ],
            ],
          },
        },
      ],
    },
    ...overrides,
  };
}

test('the Princeton rights gate admits only affirmative public-domain/attribution URIs', () => {
  assert.equal(rightsBasis('http://rightsstatements.org/vocab/NKC/1.0/'), 'nkc');
  assert.equal(rightsBasis('https://rightsstatements.org/vocab/NoC-US/1.0/'), 'no-copyright-us');
  assert.equal(rightsBasis('http://rightsstatements.org/vocab/PDM/1.0/'), 'public-domain-mark');
  assert.equal(rightsBasis('https://creativecommons.org/publicdomain/zero/1.0/'), 'cc0');
  assert.equal(rightsBasis('https://creativecommons.org/licenses/by/4.0/'), 'cc-by');
  for (const uri of [
    '',
    null,
    'http://rightsstatements.org/vocab/InC/1.0/',
    'http://rightsstatements.org/vocab/CNE/1.0/',
    'http://rightsstatements.org/vocab/NoC-OKLR/1.0/',
    'https://creativecommons.org/licenses/by-nc/4.0/',
    'https://creativecommons.org/licenses/by/4.0/deed.en',
    'https://example.org/licence',
  ]) {
    assert.equal(rightsBasis(uri), null, `${uri} must not pass the rights gate`);
  }
});

test('publication years use Date metadata and never turn a descending facsimile pair into a 1765 range', () => {
  assert.deepEqual(publicationYears(fixtureManifest()), { start: 1884, end: 1884, source: 'Date' });
  const range = fixtureManifest({
    metadata: [{ label: { eng: ['Date'] }, value: { eng: ['1949-1950'] } }],
  });
  assert.deepEqual(publicationYears(range), { start: 1949, end: 1950, source: 'Date' });
  const facsimile = fixtureManifest({
    metadata: [{ label: { eng: ['Date'] }, value: { eng: ['1983-1765'] } }],
  });
  assert.deepEqual(publicationYears(facsimile), { start: 1983, end: 1983, source: 'Date (reprint)' });
  const imprint = fixtureManifest({
    metadata: [{ label: { eng: ['Publisher'] }, value: { eng: ['[London] : Example, 1877.'] } }],
  });
  assert.deepEqual(publicationYears(imprint), { start: 1877, end: 1877, source: 'Publisher imprint' });
  const ambiguous = fixtureManifest({
    metadata: [{ label: { eng: ['Publisher'] }, value: { eng: ['London, 1877', 'Reprinted 1901'] } }],
  });
  assert.deepEqual(publicationYears(ambiguous), { start: null, end: null, source: null });
});

test('navPlace becomes a documented footprint only when it is a real polygon', () => {
  const extent = navPlaceExtent(fixtureManifest());
  assert.deepEqual(extent, { west: -75.2, east: -73.9, south: 38.9, north: 41.4 });
  assert.equal(navPlaceExtent({ navPlace: { features: [] } }), null);
  assert.equal(navPlaceExtent({}), null);
  assert.equal(
    navPlaceExtent({
      navPlace: { features: [{ geometry: { type: 'Point', coordinates: [-74, 40] } }] },
    }),
    null,
    'a point is not promoted into a map footprint',
  );
  assert.equal(
    navPlaceExtent({
      navPlace: {
        features: [
          {
            geometry: {
              type: 'Polygon',
              coordinates: [
                [
                  [179, 40],
                  [-179, 40],
                  [-179, 41],
                  [179, 41],
                  [179, 40],
                ],
              ],
            },
          },
        ],
      },
    }),
    null,
    'an antimeridian-crossing box is not silently interpreted as a world extent',
  );
});

test('a manifest builds a RUL record with verbatim title, rights URI and official holding name', () => {
  const document = { id: '0feac1a1-4308-4382-9918-589ab06700e6' };
  const { record, reason } = princetonRecord(fixtureManifest(), document);
  assert.equal(reason, null);
  assert.equal(record.id, 'princeton:0feac1a1-4308-4382-9918-589ab06700e6');
  assert.equal(record.title, 'A chart of the coast');
  assert.deepEqual(record.titleAlt, ['A chart of the coast [map].']);
  assert.equal(record.institution, 'Princeton University Library');
  assert.equal(record.heldBy, 'Princeton');
  assert.equal(record.rightsUri, 'http://rightsstatements.org/vocab/NKC/1.0/');
  assert.match(record.rights, /No Known Copyright.*NKC\/1\.0/);
  assert.equal(record.yearStart, 1884);
  assert.equal(record.yearEnd, 1884);
  assert.deepEqual(record.extent, { west: -75.2, east: -73.9, south: 38.9, north: 41.4 });
  assert.match(record.geoNote, /not a verified image georeference/);
  assert.equal(record.recordUrl, 'https://figgy.princeton.edu/catalog/0feac1a1-4308-4382-9918-589ab06700e6');
  assert.equal(record.iiifManifest, 'https://figgy.princeton.edu/concern/scanned_maps/0feac1a1-4308-4382-9918-589ab06700e6/manifest');
  assert.match(record.thumbnail, /^https:\/\/iiif-cloud\.princeton\.edu\//);
});

test('ineligible manifests produce a reason instead of a record', () => {
  const document = { id: '0feac1a1-4308-4382-9918-589ab06700e6' };
  const inCopyright = princetonRecord(fixtureManifest({ rights: 'http://rightsstatements.org/vocab/InC/1.0/' }), document);
  assert.equal(inCopyright.record, null);
  assert.match(inCopyright.reason, /rights withheld/);
  const empty = princetonRecord(fixtureManifest({ items: [] }), document);
  assert.equal(empty.record, null);
  assert.match(empty.reason, /no canvases/);
  const noThumb = princetonRecord(
    fixtureManifest({
      thumbnail: [],
      items: [
        {
          type: 'Canvas',
          items: [{ items: [{ body: { id: 'https://example.org/x.jpg', type: 'Image', service: [{ '@id': 'https://example.org/iiif/2/x' }] } }] }],
        },
      ],
    }),
    document,
  );
  assert.equal(noThumb.record, null);
  assert.match(noThumb.reason, /no Princeton image service/);
});

test('the committed Princeton shard is rights-cleared, internally consistent and registered', () => {
  assert.equal(shard.providerId, 'princeton');
  assert.equal(shard.selection.kept, shard.records.length);
  assert.ok(shard.records.length >= 7000, `expected the bulk of the 7,410 NKC records, found ${shard.records.length}`);
  assert.equal(core.shards.includes('/data/records/princeton.json'), true);
  assert.equal(core.selection['princeton:figgy'].shard, '/data/records/princeton.json');
  assert.equal(core.records.some((record) => record.providerId === 'princeton'), false, 'the core must not duplicate shard records');

  const ids = new Set();
  for (const record of shard.records) {
    assert.match(record.id, /^princeton:[0-9a-f-]{36}$/, record.id);
    assert.equal(ids.has(record.id), false, `duplicate ${record.id}`);
    ids.add(record.id);
    assert.equal(record.providerId, 'princeton');
    assert.match(record.institution, /Princeton/);
    assert.equal(rightsBasis(record.rightsUri), record.rightsBasis, `${record.id}: rights basis must match its URI`);
    assert.notEqual(record.rightsBasis, null);
    assert.ok(record.recordUrl.startsWith('https://figgy.princeton.edu/catalog/'), record.id);
    assert.ok(record.iiifManifest.startsWith('https://figgy.princeton.edu/concern/scanned_maps/'), record.id);
    assert.ok(record.thumbnail.startsWith('https://iiif-cloud.princeton.edu/'), record.id);
    assert.ok(record.imageService.startsWith('https://iiif-cloud.princeton.edu/iiif/2/'), record.id);
    assert.ok(typeof record.geoNote === 'string' && record.geoNote.length > 20, `${record.id}: an alignment note is mandatory`);
    if (record.extent) {
      const { west, east, south, north } = record.extent;
      assert.ok(west >= -180 && east <= 180 && south >= -90 && north <= 90, record.id);
      assert.ok(west < east && south < north, record.id);
    }
    if (record.yearStart != null) {
      assert.ok(Number.isInteger(record.yearStart) && Number.isInteger(record.yearEnd), record.id);
      assert.ok(record.yearStart >= 1400 && record.yearEnd <= 2100, record.id);
      assert.ok(record.yearStart <= record.yearEnd, record.id);
    }
  }
  assert.ok(ids.has('princeton:0feac1a1-4308-4382-9918-589ab06700e6'), 'stable verification example');
  const withheld = Object.values(shard.selection.withheld).reduce((sum, count) => sum + count, 0);
  assert.equal(shard.selection.kept + withheld, shard.selection.considered, 'every considered record is either kept or explained');
  assert.ok(shard.selection.verification.thumbnailOk >= 30 && shard.selection.verification.imageInfoOk >= 30);
});

